async function registerServiceWorker() {
  if (!('serviceWorker' in navigator)) return; // very old browser: the app still works online

  // If the page had a controller when it loaded, a later controller change means "an update took over".
  const hadController = Boolean(navigator.serviceWorker.controller);

  const registration = await navigator.serviceWorker.register('/sw.js', {
    scope: '/',
    updateViaCache: 'none', // always fetch sw.js and its imports from the network when checking for updates
  });

  const offerUpdate = (worker) =>
    showToast('A new version is ready.', 'Reload', () => worker.postMessage({ type: 'SKIP_WAITING' }));

  // A new worker was already installed and waiting when this page opened.
  if (registration.waiting && navigator.serviceWorker.controller) offerUpdate(registration.waiting);

  // A new worker shows up while the page is open.
  registration.addEventListener('updatefound', () => {
    const incoming = registration.installing;
    incoming?.addEventListener('statechange', () => {
      // "installed" + an existing controller = an update (not the very first install).
      if (incoming.state === 'installed' && navigator.serviceWorker.controller) offerUpdate(incoming);
    });
  });

  // The new worker has taken over: reload once so the page and the worker are the same version.
  let reloaded = false;
  navigator.serviceWorker.addEventListener('controllerchange', () => {
    if (!hadController || reloaded) return; // first install claims the page too: no reload needed
    reloaded = true;
    location.reload();
  });

  // Tabs can stay open for days. Check for a new sw.js whenever the app comes back to the front.
  document.addEventListener('visibilitychange', () => {
    if (document.visibilityState === 'visible') registration.update().catch(() => {});
  });
