// Change VERSION whenever a precached file changes. A new version means a new cache,
// filled during install while the old worker keeps serving the old files.
const VERSION = 'v1';
const STATIC_CACHE = `static-${VERSION}`;
const RUNTIME_CACHE = `runtime-${VERSION}`;

// The app shell: the minimum set of files needed to draw the UI with no network.
const PRECACHE_URLS = [
  '/index.html',
  '/offline.html',
  '/styles.css',
  '/app.js',
  '/db.js',
  '/manifest.webmanifest',
  '/icons/icon-192.png',
  '/icons/icon-512.png',
];

self.addEventListener('install', (event) => {
  // waitUntil keeps the worker alive until the promise settles.
  // If any file fails to download, addAll rejects, install fails, and the old worker stays in charge.
  event.waitUntil(
    caches.open(STATIC_CACHE).then((cache) =>
      // cache: 'reload' skips the browser's HTTP cache so we store fresh copies.
      cache.addAll(PRECACHE_URLS.map((url) => new Request(url, { cache: 'reload' })))
    )
  );
  // No skipWaiting() here: the page asks for it when the user taps "Reload" (see the message handler).
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      // Delete caches left behind by older versions of this worker.
      const keep = [STATIC_CACHE, RUNTIME_CACHE];
      const names = await caches.keys();
      await Promise.all(names.filter((name) => !keep.includes(name)).map((name) => caches.delete(name)));
      // Take control of pages that are already open (otherwise they are controlled only after a reload).
      await self.clients.claim();
    })()
  );
});

self.addEventListener('fetch', (event) => {
  const { request } = event;
  const url = new URL(request.url);

  // Not calling respondWith() means "browser, handle this one as usual".
  if (request.method !== 'GET') return;            // writes always go to the network
  if (url.origin !== self.location.origin) return; // other sites: not our business
  if (url.pathname.startsWith('/api/')) return;    // task data lives in IndexedDB, not in the HTTP cache

  // A page load (typing the URL, tapping the icon, following a link).
  if (request.mode === 'navigate') {
    event.respondWith(networkFirst(request, { fallbackUrl: '/index.html' }));
    return;
  }

  // Files from the precache list.
  if (PRECACHE_URLS.includes(url.pathname)) {
    event.respondWith(cacheFirst(request));
    return;
  }

  // Everything else on our origin (extra icons, images added later).
  event.respondWith(staleWhileRevalidate(request, event));
});

// CACHE FIRST: answer from the cache; go to the network only on a miss.
// Fastest. Right for files that only change when VERSION changes.
async function cacheFirst(request) {
  const cached = await caches.match(request);
  if (cached) return cached;
  const response = await fetch(request);
  if (response.ok) {
    const cache = await caches.open(RUNTIME_CACHE);
    cache.put(request, response.clone()); // a Response body can be read once, so store a copy
  }
  return response;
}

// NETWORK FIRST: try the network, fall back to the cache if it fails or takes too long.
// Freshest. Right for HTML, where an old copy is acceptable but a new one is better.
async function networkFirst(request, { timeoutMs = 2500, fallbackUrl } = {}) {
  const cache = await caches.open(RUNTIME_CACHE);
  try {
    const response = await fetch(request, { signal: AbortSignal.timeout(timeoutMs) });
    if (response.ok) cache.put(request, response.clone());
    return response;
  } catch (error) {
    // Offline, DNS failure or timeout. Try this exact URL, then the precached shell.
    return (await caches.match(request)) || (await caches.match(fallbackUrl)) || (await caches.match('/offline.html'));
  }
}

// STALE WHILE REVALIDATE: answer from the cache at once, and refresh the cache in the background.
// Fast, and at most one visit out of date. Right for avatars, article images, non-critical data.
async function staleWhileRevalidate(request, event) {
  const cache = await caches.open(RUNTIME_CACHE);
  const cached = await cache.match(request);
  const refresh = fetch(request)
    .then((response) => {
      if (response.ok) cache.put(request, response.clone());
      return response;
    })
    .catch(() => undefined);
  // Keep the worker alive until the background refresh has finished.
  event.waitUntil(refresh);
  return cached || (await refresh) || Response.error();
}

// IndexedDB is event-based; wrap a request in a Promise so we can use await.
const promisify = (request) =>
  new Promise((resolve, reject) => {
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });

function openDB() {
  if (dbPromise) return dbPromise;
  const request = indexedDB.open(DB_NAME, DB_VERSION);

  // Runs only when DB_VERSION is higher than what the browser has stored.
  // This is the one place where object stores and indexes may be created.
  request.onupgradeneeded = () => {
    const db = request.result;
    if (!db.objectStoreNames.contains('tasks')) {
      db.createObjectStore('tasks', { keyPath: 'id' });
    }
    if (!db.objectStoreNames.contains('outbox')) {
      // autoIncrement gives each queued change a rising number, so we can replay them in order.
      db.createObjectStore('outbox', { keyPath: 'key', autoIncrement: true });
    }
  };

  dbPromise = promisify(request);
  return dbPromise;
}

// Run `work` inside one transaction and resolve when the transaction has committed.
async function withTx(storeNames, mode, work) {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(storeNames, mode);
    let result;
    tx.oncomplete = () => resolve(result);
    tx.onerror = () => reject(tx.error);
    tx.onabort = () => reject(tx.error || new Error('Transaction aborted'));
    const out = work(tx);
    if (out instanceof IDBRequest) out.onsuccess = () => { result = out.result; };
    else result = out;
  });
}

function getAllTasks() {
  return withTx(['tasks'], 'readonly', (tx) => tx.objectStore('tasks').getAll());
}

// Save the task AND queue the change for the server in the same transaction.
// Either both are stored or neither is, so the outbox can never miss a change.
function saveTask(task) {
  return withTx(['tasks', 'outbox'], 'readwrite', (tx) => {
    tx.objectStore('tasks').put(task);
    tx.objectStore('outbox').add({ op: 'put', taskId: task.id, task, queuedAt: Date.now() });
  });
}

function deleteTask(id) {
  return withTx(['tasks', 'outbox'], 'readwrite', (tx) => {
    tx.objectStore('tasks').delete(id);
    tx.objectStore('outbox').add({ op: 'delete', taskId: id, queuedAt: Date.now() });
  });
}

function getOutbox() {
  return withTx(['outbox'], 'readonly', (tx) => tx.objectStore('outbox').getAll());
}

function removeFromOutbox(key) {
  return withTx(['outbox'], 'readwrite', (tx) => tx.objectStore('outbox').delete(key));
}

// Replace local tasks with the server's list. Only called when the outbox is empty,
// so there is no local change that this could overwrite.
function replaceAllTasks(tasks) {
  return withTx(['tasks'], 'readwrite', (tx) => {
    const store = tx.objectStore('tasks');
    store.clear();
    tasks.forEach((task) => store.put(task));
  });
}

