// Send queued changes to the server, oldest first.
// Throws on a network failure or a 5xx, which tells the caller "try again later".
async function sendOutbox() {
  const entries = await getOutbox();
  for (const entry of entries) {
    const url = '/api/tasks/' + encodeURIComponent(entry.taskId);
    const response = entry.op === 'delete'
      ? await fetch(url, { method: 'DELETE' })
      : await fetch(url, {
          method: 'PUT',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(entry.task),
        });

    // 5xx = the server is having a bad moment: keep the entry and retry later.
    if (response.status >= 500) throw new Error('Server error ' + response.status);
    // 2xx = stored. 4xx = the server will never accept this change, so retrying is pointless.
    await removeFromOutbox(entry.key);
  }
  return entries.length;
}

// The page and the service worker may both try to flush at the same moment.
// A Web Lock makes them take turns; the second caller finds an empty outbox.
function flushOutbox() {
  if (scope.navigator && scope.navigator.locks) {
    return scope.navigator.locks.request('outbox-flush', sendOutbox);
  }
  return sendOutbox(); // No Web Locks: PUT and DELETE by id are safe to repeat anyway.
}

// Ask the server for the current list, but only if nothing local is waiting to be sent.
async function pullFromServer() {
  if ((await getOutbox()).length > 0) return false;
  const response = await fetch('/api/tasks', { cache: 'no-store' });
  if (!response.ok) throw new Error('Server error ' + response.status);
  const tasks = await response.json();
  // A change may have been queued while we were waiting for the response.
  if ((await getOutbox()).length > 0) return false;
  await replaceAllTasks(tasks);
  return true;
}

async function sync() {
  // Safety net first: ask the browser to wake the service worker when the connection
  // returns, even if this tab has been closed by then. (Chromium only.)
  try {
    const registration = await navigator.serviceWorker?.ready;
    if (registration && 'sync' in registration) await registration.sync.register('flush-outbox');
  } catch { /* permission denied or unsupported: the direct attempt below still runs */ }

  // Then try right now from the page. This is the only path in Safari and Firefox.
  try {
    await TaskDB.flushOutbox();
    const changed = await TaskDB.pullFromServer();
    state.syncError = false;
    if (changed) state.tasks = await TaskDB.getAllTasks();
    render();
  } catch {
    state.syncError = true; // offline or server down: changes stay in the outbox
  }
  renderSyncChip();
}

// Moments when a retry is likely to succeed.
window.addEventListener('online', sync);
window.addEventListener('offline', renderSyncChip);
document.addEventListener('visibilitychange', () => { if (document.visibilityState === 'visible') sync(); });
$('sync-chip').addEventListener('click', sync);
