// Background Sync: the browser fires this once it believes there is a connection,
// even if the user closed the tab after making changes offline.
self.addEventListener('sync', (event) => {
  if (event.tag !== 'flush-outbox') return;
  // If this promise rejects, the browser schedules another attempt with a growing delay.
  event.waitUntil(TaskDB.flushOutbox().then(() => tellPages({ type: 'OUTBOX_FLUSHED' })));
});

async function tellPages(message) {
  const pages = await self.clients.matchAll({ type: 'window', includeUncontrolled: true });
  pages.forEach((page) => page.postMessage(message));
}

async function handleTasks(req, res, pathname) {
  const id = decodeURIComponent(pathname.slice('/api/tasks/'.length));

  if (req.method === 'GET' && pathname === '/api/tasks') return send(res, 200, [...tasks.values()]);

  // PUT is an upsert keyed by the client's id, so receiving the same request twice changes nothing.
  // That is what makes "retry until it works" safe.
  if (req.method === 'PUT' && id) {
    const task = await readBody(req);
    if (typeof task.title !== 'string' || !task.title.trim() || task.id !== id) {
      return send(res, 400, { error: 'A task needs an id that matches the URL and a title.' });
    }
    const current = tasks.get(id);
    // Last write wins: ignore a change that is older than what we already hold.
    if (!current || task.updatedAt >= current.updatedAt) {
      tasks.set(id, { id, title: task.title.trim().slice(0, 140), done: Boolean(task.done), createdAt: task.createdAt, updatedAt: task.updatedAt });
      saveTasks();
    }
    return send(res, 200, tasks.get(id));
  }

  // Deleting something that is already gone is still a success.
  if (req.method === 'DELETE' && id) {
    tasks.delete(id);
    saveTasks();
    return send(res, 204);
  }
  return send(res, 404, { error: 'Not found' });
}

// The server's public key arrives as base64url text; subscribe() wants raw bytes.
function base64UrlToBytes(text) {
  const padded = (text + '='.repeat((4 - (text.length % 4)) % 4)).replace(/-/g, '+').replace(/_/g, '/');
  return Uint8Array.from(atob(padded), (ch) => ch.charCodeAt(0));
}

async function setUpPushUI() {
  const supported = 'serviceWorker' in navigator && 'PushManager' in window && 'Notification' in window;
  if (!supported) {
    // On iPhone, push exists only inside the installed (home screen) app.
    if (isIOS && !isStandalone) {
      $('push-note').textContent = 'Reminders work after you add this app to your Home Screen.';
      $('push-note').hidden = false;
    }
    return;
  }
  const registration = await navigator.serviceWorker.ready;
  const existing = await registration.pushManager.getSubscription();
  $('push-btn').hidden = Boolean(existing);
  $('push-test-btn').hidden = !existing;
}

async function enablePush() {
  // 1. Ask permission. Call this from a tap, never on page load: browsers ignore or punish that.
  const permission = await Notification.requestPermission();
  if (permission !== 'granted') {
    showToast(permission === 'denied' ? 'Notifications are blocked in your browser settings.' : 'No reminders for now.');
    return;
  }

  // 2. Get the server's public key and subscribe with the browser's push service.
  const keyResponse = await fetch('/api/push/public-key');
  if (!keyResponse.ok) { showToast('The server is not set up for push yet.'); return; }
  const { publicKey } = await keyResponse.json();

  const registration = await navigator.serviceWorker.ready;
  const subscription = await registration.pushManager.subscribe({
    userVisibleOnly: true, // a promise that every push will show a notification; required
    applicationServerKey: base64UrlToBytes(publicKey),
  });

  // 3. Send the subscription (an endpoint URL plus two keys) to our server to store.
  await fetch('/api/push/subscribe', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(subscription),
  });

  showToast('Reminders are on.');
  setUpPushUI();
}

