// The user tapped the notification.
self.addEventListener('notificationclick', (event) => {
  event.notification.close();
  const target = new URL(event.notification.data.url, self.location.origin).href;
  event.waitUntil(
    (async () => {
      const pages = await self.clients.matchAll({ type: 'window', includeUncontrolled: true });
      // Reuse an open window if there is one, otherwise open a new one.
      const open = pages.find((page) => new URL(page.url).origin === self.location.origin);
      if (open) {
        await open.focus();
        if (open.url !== target && 'navigate' in open) await open.navigate(target);
      } else {
        await self.clients.openWindow(target);
      }
    })()
  );
});

// Web Push needs a key pair (VAPID). The public half goes to the browser, the private half
// signs every push so the push service knows it came from this server.
let webpush = null;
try { webpush = require('web-push'); } catch { /* run `npm install` to enable push */ }

let vapid = readJSON('vapid.json', null);
if (webpush) {
  if (!vapid) { vapid = webpush.generateVAPIDKeys(); writeJSON('vapid.json', vapid); } // keep this file private
  // The subject is a contact address the push service can use if your server misbehaves.
  webpush.setVapidDetails('mailto:you@example.com', vapid.publicKey, vapid.privateKey);
}

let subscriptions = readJSON('subscriptions.json', []);
const saveSubscriptions = () => writeJSON('subscriptions.json', subscriptions);

async function sendToAll(payload) {
  const results = await Promise.allSettled(
    subscriptions.map((sub) => webpush.sendNotification(sub, JSON.stringify(payload), { TTL: 60 * 60 }))
  );
  // 404 or 410 from the push service means this subscription is gone for good: forget it.
  subscriptions = subscriptions.filter((_, i) => {
    const r = results[i];
    return !(r.status === 'rejected' && [404, 410].includes(r.reason?.statusCode));
  });
  saveSubscriptions();
  return results.filter((r) => r.status === 'fulfilled').length;
}

async function handlePush(req, res, pathname) {
  if (!webpush) return send(res, 501, { error: 'Push is off. Run "npm install" in the project folder, then restart.' });

  if (req.method === 'GET' && pathname === '/api/push/public-key') {
    return send(res, 200, { publicKey: vapid.publicKey });
  }
  if (req.method === 'POST' && pathname === '/api/push/subscribe') {
    const sub = await readBody(req);
    if (!sub.endpoint || !sub.keys) return send(res, 400, { error: 'Not a push subscription.' });
    if (!subscriptions.some((s) => s.endpoint === sub.endpoint)) { subscriptions.push(sub); saveSubscriptions(); }
    return send(res, 201, { ok: true });
  }
  if (req.method === 'POST' && pathname === '/api/push/test') {
    const { title = 'Tasks', body = 'Test reminder', delaySeconds = 0 } = await readBody(req);
    const delay = Math.min(Number(delaySeconds) || 0, 60) * 1000;
    setTimeout(() => sendToAll({ title, body, url: '/' }).catch(console.error), delay);
    return send(res, 202, { queued: subscriptions.length });
  }
  return send(res, 404, { error: 'Not found' });
}

